import java.util.*;
import java.io.*;

public class Main {
    static class ListNode {
        int val;
        ListNode next;
        ListNode(int val) { this.val = val; }
    }

    static ListNode getIntersectionNode(ListNode headA, ListNode headB) {
        // Write your solution here
        return null;
    }

    static ListNode build(int[] vals, int from, int to, ListNode tail) {
        ListNode head = tail;
        for (int i = to - 1; i >= from; i--) {
            ListNode node = new ListNode(vals[i]);
            node.next = head;
            head = node;
        }
        return head;
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int a = (int) in.nval;
        in.nextToken();
        int b = (int) in.nval;
        in.nextToken();
        int c = (int) in.nval;
        int[] vals = new int[a + b + c];
        for (int i = 0; i < a + b + c; i++) {
            in.nextToken();
            vals[i] = (int) in.nval;
        }
        ListNode shared = build(vals, a + b, a + b + c, null);
        ListNode headA = build(vals, 0, a, shared);
        ListNode headB = build(vals, a, a + b, shared);
        ListNode node = getIntersectionNode(headA, headB);
        System.out.println(node != null ? node.val : -1);
    }
}
